/**
 * Discovers services generated by `pa app add data-source` at build time.
 *
 * Generated files live in src/generated/services and don't exist until data
 * sources are added. `import.meta.glob` resolves to an empty map when the
 * folder is missing, so the app compiles and runs on sample data before the
 * Dataverse tables / Outlook connector are connected.
 */
import { dataverseTables, type DataverseTableKey } from "@/config/dataverse-schema"

export interface GetAllOptions {
  select?: string[]
  filter?: string
  orderBy?: string[]
  top?: number
  maxPageSize?: number
  skipToken?: string
}

export interface OperationResult<T> {
  success: boolean
  data: T
  error?: unknown
  skipToken?: string
}

export type DataverseRow = Record<string, unknown>

export interface TableService {
  getAll(options?: GetAllOptions): Promise<OperationResult<DataverseRow[]>>
}

export interface OutlookService {
  SendEmailV2(emailMessage: {
    To: string
    Subject: string
    Body: string
    Cc?: string
    Importance?: "Low" | "Normal" | "High"
  }): Promise<OperationResult<unknown>>
}

type ModuleExports = Record<string, unknown>

const serviceModules = import.meta.glob<ModuleExports>("../../generated/services/*.ts")

function fileName(path: string) {
  return path.split("/").pop()!.replace(/\.ts$/, "")
}

function pickExport<T>(mod: ModuleExports, method: string): T | undefined {
  for (const value of Object.values(mod)) {
    if (value && (typeof value === "function" || typeof value === "object") && typeof (value as Record<string, unknown>)[method] === "function") {
      return value as T
    }
  }
  return undefined
}

function dataSourceNameOf(service: unknown): string | undefined {
  const name = (service as { dataSourceName?: unknown }).dataSourceName
  return typeof name === "string" ? name.toLowerCase() : undefined
}

/** Plural entity-set names the generator may produce for a logical name. */
function entitySetCandidates(logicalName: string) {
  const n = logicalName.toLowerCase()
  return new Set([n, `${n}s`, `${n}es`, n.endsWith("y") ? `${n.slice(0, -1)}ies` : `${n}s`])
}

async function findTableService(logicalName: string): Promise<TableService | undefined> {
  const candidates = entitySetCandidates(logicalName)
  let fallback: TableService | undefined

  for (const [path, load] of Object.entries(serviceModules)) {
    const base = fileName(path).toLowerCase().replace(/service$/, "")
    if (!candidates.has(base)) continue
    const service = pickExport<TableService>(await load(), "getAll")
    if (!service) continue
    const dsName = dataSourceNameOf(service)
    if ((dsName && candidates.has(dsName)) || candidates.has(base)) return service
    fallback ??= service
  }
  return fallback
}

export async function findOutlookService(): Promise<OutlookService | undefined> {
  for (const [path, load] of Object.entries(serviceModules)) {
    if (!/office365outlook/i.test(fileName(path))) continue
    const service = pickExport<OutlookService>(await load(), "SendEmailV2")
    if (service) return service
  }
  return undefined
}

export type TableServices = Record<DataverseTableKey, TableService>

export function hasAllTableServices(services: Partial<TableServices>): services is TableServices {
  return !!services.rfqCase && !!services.rfqCaseLine && !!services.rfqReply && !!services.rfqReplyLine && !!services.vendor
}

export async function discoverTableServices(): Promise<{
  services: Partial<TableServices>
  missing: string[]
}> {
  const services: Partial<TableServices> = {}
  const missing: string[] = []
  for (const key of Object.keys(dataverseTables) as DataverseTableKey[]) {
    const service = await findTableService(dataverseTables[key].logicalName)
    if (service) services[key] = service
    else missing.push(dataverseTables[key].logicalName)
  }
  return { services, missing }
}

export function hasGeneratedServices() {
  return Object.keys(serviceModules).length > 0
}
